void LoginStateAsyncWaiter::GetSessionState(
    GetSessionStateResultPtr* out_result) {
  base::RunLoop loop;
  proxy_->GetSessionState(
      base::BindOnce(
          [](base::RunLoop* loop,
             GetSessionStateResultPtr* out_result
,
             GetSessionStateResultPtr result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

